147	/// Very basic check that code does indeed run in the VM.
148	pub(crate) fn runs_in_vm(
149	    script: BuiltPackage,
150	    script_data: Option<Vec<u8>>,
151	    witness_data: Option<Vec<Vec<u8>>>,
152	) -> Result<VMExecutionResult> {
153	    match script.descriptor.target {
154	        BuildTarget::Fuel => {
155	            let storage = MemoryStorage::default();
156	
157	            let rng = &mut StdRng::seed_from_u64(2322u64);
158	            let maturity = 1.into();
159	            let script_data = script_data.unwrap_or_default();
160	            let block_height = (u32::MAX >> 1).into();
161	            // The default max length is 1MB which isn't enough for the bigger tests.
162	            let max_size = 64 * 1024 * 1024;
163	            let script_params = ScriptParameters::DEFAULT
164	                .with_max_script_length(max_size)
165	                .with_max_script_data_length(max_size);
166	            let tx_params = TxParameters::DEFAULT.with_max_size(max_size);
167	            let params = ConsensusParameters::V1(ConsensusParametersV1 {
168	                script_params,
169	                tx_params,
170	                ..Default::default()
171	            });
172	            let mut tb = TransactionBuilder::script(script.bytecode.bytes, script_data);
173	
174	            tb.with_params(params)
175	                .add_unsigned_coin_input(
176	                    SecretKey::random(rng),
177	                    rng.gen(),
178	                    1,
179	                    Default::default(),
180	                    rng.gen(),
181	                )
182	                .maturity(maturity);
183	
184	            if let Some(witnesses) = witness_data {
185	                for witness in witnesses {
186	                    tb.add_witness(witness.into());
187	                }
188	            }
189	            let gas_price = 0;
190	            let consensus_params = tb.get_params().clone();
191	
192	            let params = ConsensusParameters::default();
193	            // Temporarily finalize to calculate `script_gas_limit`
194	            let tmp_tx = tb.clone().finalize();
195	            // Get `max_gas` used by everything except the script execution. Add `1` because of rounding.
196	            let max_gas =
197	                tmp_tx.max_gas(consensus_params.gas_costs(), consensus_params.fee_params()) + 1;
198	            // Increase `script_gas_limit` to the maximum allowed value.
199	            tb.script_gas_limit(consensus_params.tx_params().max_gas_per_tx() - max_gas);
200	
201	            let tx = tb
202	                .finalize_checked(block_height)
203	                .into_ready(gas_price, params.gas_costs(), params.fee_params())
204	                .map_err(|e| anyhow::anyhow!("{e:?}"))?;
205	
206	            let mem_instance = MemoryInstance::new();
207	            let mut i: Interpreter<_, _, _, NotSupportedEcal> =
208	                Interpreter::with_storage(mem_instance, storage, Default::default());
209	            let transition = i.transact(tx).map_err(anyhow::Error::msg)?;
210	
211	            Ok(VMExecutionResult::Fuel(
212	                *transition.state(),
213	                transition.receipts().to_vec(),
214	            ))
215	        }
216	        BuildTarget::EVM => {
217	            let mut evm = revm::new();
218	            evm.database(revm::InMemoryDB::default());
219	            evm.env = revm::Env::default();
220	
221	            // Transaction to create the smart contract
222	            evm.env.tx.transact_to = revm::TransactTo::create();
223	            evm.env.tx.data = bytes::Bytes::from(script.bytecode.bytes.into_boxed_slice());
224	            let result = evm.transact_commit();
225	
226	            match result.out {
227	                revm::TransactOut::None => Err(anyhow!("Could not create smart contract")),
228	                revm::TransactOut::Call(_) => todo!(),
229	                revm::TransactOut::Create(ref _bytes, account_opt) => {
230	                    match account_opt {
231	                        Some(account) => {
232	                            evm.env.tx.transact_to = revm::TransactTo::Call(account);
233	
234	                            // Now issue a call.
235	                            //evm.env.tx. = bytes::Bytes::from(script.bytecode.into_boxed_slice());
236	                            let result = evm.transact_commit();
237	                            Ok(VMExecutionResult::Evm(result))
238	                        }
239	                        None => todo!(),
240	                    }
241	                }
242	            }
243	        }
244	        BuildTarget::MidenVM => {
245	            use miden::{Assembler, ProgramInputs};
246	
247	            // instantiate the assembler
248	            let assembler = Assembler::default();
249	
250	            let bytecode_str = std::str::from_utf8(&script.bytecode.bytes)?;
251	
252	            // compile Miden assembly source code into a program
253	            let program = assembler.compile(bytecode_str).unwrap();
254	
255	            // execute the program with no inputs
256	            let _trace = miden::execute(&program, &ProgramInputs::none()).unwrap();
257	
258	            let execution_trace = miden::execute(&program, &ProgramInputs::none())
259	                .map_err(|e| anyhow::anyhow!("Failed to execute on MidenVM: {e:?}"))?;
260	
261	            Ok(VMExecutionResult::MidenVM(execution_trace))
262	        }
263	    }
264	}
